Bornology.IsBounded.exists_bound_of_norm_Ks.{u_1} {X : Type u_1} {a : ℕ} {K : X → X → ℂ}
  [PseudoMetricSpace X] [KernelProofData a K] {A : Set X} (hA : Bornology.IsBounded A) (s : ℤ) :
